<script lang="ts">
	import { onMount } from 'svelte'; import { goto } from '$app/navigation'; import { page } from '$app/state'; import { csrfHeaders, idempotencyKey } from '$lib/api/client';
	import DocumentUploader from '$lib/components/DocumentUploader.svelte';
	import { productLabel } from '$lib/product-language';
	import { readLocal, writeLocal, removeLocal, rememberSaleItem, type SavedSaleItem } from '$lib/product-tools';
	let organizations:any[]=$state([]), customers:any[]=$state([]), organizationID=$state(''), selectedBuyer=$state(''), busy=$state(false), error=$state(''), success=$state('');
	let createRequestKey=$state('');
	let buyerUserID=$state(''), buyerBusinessID=$state(''), buyerLegalName=$state(''), principal=$state(''), goods=$state(''), dueDate=$state(''), collectionAt=$state(''), graceHours=$state(24), invoiceReference=$state(''), invoiceFile:File|null=$state(null);
	let scheduleType=$state('one_time'), scheduleCount=$state(2), scheduleCadence=$state('monthly'), monthEndPolicy=$state('last_day'), customSchedule=$state('');
	let customerSearch=$state(''),savedItems:SavedSaleItem[]=$state([]),draftReady=$state(false),draftMessage=$state('');
	let errorSummary:HTMLParagraphElement=$state()!;
	function showError(value:string){error=value;queueMicrotask(()=>errorSummary?.focus())}
	async function loadCustomers(){customers=[];selectedBuyer='';buyerUserID='';buyerBusinessID='';buyerLegalName='';if(!organizationID)return;const r=await fetch(`/api/v1/organizations/${organizationID}/customers`,{credentials:'include'});if(r.ok)customers=(await r.json()).customers??[];}
	function chooseBuyer(){const customer=customers.find((item)=>item.buyer_user_id===selectedBuyer);buyerUserID=customer?.buyer_user_id??'';buyerBusinessID=customer?.buyer_business_id??'';buyerLegalName=customer?.legal_name??'';}
	const visibleCustomers=$derived(customers.filter((item)=>`${item.trading_name??''} ${item.legal_name??''}`.toLowerCase().includes(customerSearch.trim().toLowerCase())));
	function draftKey(){return `kredit:sale-draft:${organizationID||'new'}`}
	function saveDraft(){if(!draftReady||!organizationID)return;writeLocal(draftKey(),{selectedBuyer,principal,goods,dueDate,collectionAt,graceHours,invoiceReference,scheduleType,scheduleCount,scheduleCadence,monthEndPolicy,customSchedule})}
	function clearDraft(){removeLocal(draftKey());principal='';goods='';dueDate='';collectionAt='';invoiceReference='';customSchedule='';draftMessage='Unfinished sale cleared.'}
	function useSaved(item:SavedSaleItem){goods=item.name;principal=item.amount;saveDraft()}
	function practise(){goods='10 cartons of cooking oil';principal='100,000';const due=new Date();due.setDate(due.getDate()+30);dueDate=due.toISOString().slice(0,10);const collect=new Date(due);collect.setDate(collect.getDate()+1);collectionAt=collect.toISOString().slice(0,16);graceHours=24;draftMessage='Sample details added. Choose a customer and change anything you want.';saveDraft()}
	onMount(async()=>{savedItems=readLocal<SavedSaleItem[]>('kredit:saved-sale-items',[]);const r=await fetch('/api/v1/organizations',{credentials:'include'});if(r.ok){const d=await r.json();organizations=d.organizations??[];organizationID=organizations[0]?.id??'';await loadCustomers();const params=page.url.searchParams;const repeated=params.has('customer')||params.has('goods');const saved=readLocal<any>(draftKey(),null);if(saved&&!repeated){selectedBuyer=saved.selectedBuyer??'';principal=saved.principal??'';goods=saved.goods??'';dueDate=saved.dueDate??'';collectionAt=saved.collectionAt??'';graceHours=saved.graceHours??24;invoiceReference=saved.invoiceReference??'';scheduleType=saved.scheduleType??'one_time';scheduleCount=saved.scheduleCount??2;scheduleCadence=saved.scheduleCadence??'monthly';monthEndPolicy=saved.monthEndPolicy??'last_day';customSchedule=saved.customSchedule??'';chooseBuyer();draftMessage='Your unfinished sale is back.'}else if(repeated){selectedBuyer=params.get('customer')??'';goods=params.get('goods')??'';principal=params.get('amount')??'';chooseBuyer();draftMessage='The customer and last sale details are ready. Check them before saving.'}draftReady=true;}});
	async function uploadInvoice(){if(!invoiceFile)return '';if(invoiceFile.size>2*1024*1024)throw new Error('For this form, the invoice must be 2 MiB or smaller.');const contentBase64=await new Promise<string>((resolve,reject)=>{const reader=new FileReader();reader.onerror=()=>reject(new Error('The invoice could not be read.'));reader.onload=()=>resolve(String(reader.result).split(',')[1]??'');reader.readAsDataURL(invoiceFile!);});const response=await fetch(`/api/v1/organizations/${organizationID}/documents`,{method:'POST',credentials:'include',headers:{'Content-Type':'application/json','Idempotency-Key':idempotencyKey(),...csrfHeaders()},body:JSON.stringify({purpose:'credit_invoice',file_name:invoiceFile.name,content_type:invoiceFile.type,retention_class:'financial_agreement',content_base64:contentBase64})});const result=await response.json().catch(()=>({}));if(!response.ok)throw new Error(result.detail??'The invoice could not be uploaded.');return result.document?.sha256??'';}
	function customItems(){if(scheduleType!=='custom')return [];return customSchedule.split('\n').filter(Boolean).map((line)=>{const [amount,date]=line.split(',').map((value)=>value.trim());return {amount_kobo:Math.round(Number((amount??'').replace(/,/g,''))*100),due_date:date};});}
	async function submit(event:SubmitEvent){event.preventDefault();error='';success='';busy=true;const amount=Math.round(Number(principal.replace(/,/g,''))*100);if(!organizationID||!buyerUserID||!buyerBusinessID||!buyerLegalName||!goods||!dueDate||!collectionAt||amount<=0){showError('Complete every required field with a valid amount.');busy=false;return;}try{const invoiceDocumentHash=await uploadInvoice();if(!createRequestKey)createRequestKey=idempotencyKey();const r=await fetch(`/api/v1/organizations/${organizationID}/credit-requests`,{method:'POST',credentials:'include',headers:{'Content-Type':'application/json','Idempotency-Key':createRequestKey,...csrfHeaders()},body:JSON.stringify({buyer_user_id:buyerUserID,buyer_business_id:buyerBusinessID,buyer_legal_name:buyerLegalName,principal_kobo:amount,goods_description:goods,invoice_reference:invoiceReference,invoice_document_hash:invoiceDocumentHash,due_date:dueDate,grace_hours:graceHours,collection_at:new Date(collectionAt).toISOString(),schedule_type:scheduleType,schedule_count:Number(scheduleCount),schedule_cadence:scheduleType==='custom'?'custom':scheduleCadence,month_end_policy:monthEndPolicy,custom_schedule_items:customItems()})});const d=await r.json().catch(()=>({}));if(!r.ok){showError(d.detail??'The sale could not be saved.');return;}rememberSaleItem(goods,principal);removeLocal(draftKey());createRequestKey='';await goto(`/app/credit/${d.request.id}?organization=${organizationID}`);}catch(cause){showError(cause instanceof Error?cause.message:'The sale could not be saved.');}finally{busy=false;}}
</script>
<svelte:head><title>Add a sale — Kredit</title></svelte:head>
<main class="shell workspace form-page"><div class="page-heading"><div><p class="eyebrow">Add a sale</p><h1>Who took the goods?</h1><p class="lede">Add the customer, goods, money and payment day. Your customer will see the same thing before saying yes.</p></div><span class="draft-badge">Not sent yet</span></div>
{#if draftMessage}<p class="draft-message" role="status">{draftMessage} <button type="button" onclick={clearDraft}>Clear</button></p>{/if}{#if error}<p bind:this={errorSummary} class="error" role="alert" tabindex="-1"><strong>Please check:</strong> {error}</p>{/if}{#if success}<p class="success" role="status">{success}</p>{/if}
<div class="practice"><div><strong>Is this your first sale?</strong><p>Use sample details to see how the form works. Nothing is sent until you save and send the sale.</p></div><button type="button" onclick={practise}>Use sample details</button></div>
<form onsubmit={submit} oninput={saveDraft} onchange={saveDraft}><section class="form-card"><b>01</b><div><h2>Choose the customer</h2><div class="form-grid"><label>Your business<select bind:value={organizationID} onchange={loadCustomers} required>{#each organizations as org}<option value={org.id}>{org.trading_name||org.legal_name}</option>{/each}</select></label>{#if customers.length}<label>Find customer<input bind:value={customerSearch} type="search" placeholder="Type the name" autocomplete="off" /></label><label>Customer<select bind:value={selectedBuyer} onchange={chooseBuyer} required><option value="">Choose a customer</option>{#each visibleCustomers as customer}<option value={customer.buyer_user_id}>{customer.trading_name||customer.legal_name}</option>{/each}</select></label><label>Customer name<input value={buyerLegalName} readonly /></label><label>Customer check<input value={productLabel(customers.find((item)=>item.buyer_user_id===selectedBuyer)?.state, 'Choose a customer')} readonly /></label>{:else}<div class="no-customers"><strong>You have not added a customer.</strong><p>Add the customer first. They will check their details through a private link.</p><a class="primary" href="/app/customers/new">Add a customer</a></div>{/if}</div></div></section><section class="form-card"><b>02</b><div><h2>Add the goods and money</h2>{#if savedItems.length}<div class="saved-items"><strong>Use goods you sold before</strong>{#each savedItems.slice(0,4) as item}<button type="button" onclick={()=>useSaved(item)}>{item.name} · ₦{item.amount}</button>{/each}</div>{/if}<div class="form-grid"><label>Money to pay (₦)<input bind:value={principal} inputmode="decimal" placeholder="1,200,000" required /></label><label>What goods did they take?<textarea bind:value={goods} rows="4" required></textarea></label><label>Invoice number <small>if you have one</small><input bind:value={invoiceReference} maxlength="120" /></label><div><DocumentUploader accept="application/pdf,image/jpeg,image/png" disabled={busy} onselect={(file)=>invoiceFile=file} />{#if invoiceFile}<small>{invoiceFile.name}</small>{/if}</div><label>First payment day<input type="date" bind:value={dueDate} required /></label><label>Day Kredit may debit if unpaid<input type="datetime-local" bind:value={collectionAt} required /></label><label>Extra hours after payment day<input type="number" min="0" max="720" bind:value={graceHours} /></label><label>How will they pay?<select bind:value={scheduleType}><option value="one_time">One payment</option><option value="equal">Same amount many times</option><option value="custom">Different amounts</option></select></label>{#if scheduleType==='equal'}<label>How many payments?<input type="number" min="2" max="60" bind:value={scheduleCount} required /></label><label>How often?<select bind:value={scheduleCadence}><option value="weekly">Every week</option><option value="fortnightly">Every two weeks</option><option value="monthly">Every month</option></select></label>{#if scheduleCadence==='monthly'}<label>If a month is shorter<select bind:value={monthEndPolicy}><option value="last_day">Use the last day</option><option value="cap">Use the nearest day</option></select></label>{/if}{:else if scheduleType==='custom'}<label class="wide">Write each payment<textarea bind:value={customSchedule} rows="5" placeholder={'600000, 2026-09-30\n600000, 2026-10-30'} required></textarea><small>One payment on each line: amount, then date. All payments must add up to the money owed.</small></label>{/if}</div></div></section><section class="form-card review"><b>03</b><div><h2>Check before saving</h2><p><strong>{buyerLegalName||'Choose a customer'}</strong> will see that they took <strong>{goods||'the goods'}</strong> and must pay <strong>₦{principal||'0'}</strong>{dueDate?` by ${new Date(`${dueDate}T12:00:00`).toLocaleDateString('en-NG')}`:''}.</p><p>Kredit will not start a bank debit before the date and time you entered.</p></div></section><div class="form-actions"><a href="/app/overview">Go back</a><button class="primary" disabled={busy||!buyerUserID}>{busy?'Saving…':'Save this sale'}</button></div></form></main>
<style>.form-page{max-width:68rem}.page-heading{display:flex;justify-content:space-between;gap:2rem;padding-bottom:2rem;border-bottom:3px solid #17181b}.page-heading h1{font-family:Georgia,'Times New Roman',serif;font-size:clamp(3rem,6vw,5.2rem);font-weight:500;line-height:.92;letter-spacing:-.055em;margin:.5rem 0}.draft-badge{height:max-content;padding:.55rem .8rem;color:#17181b;background:#e85f3d;font-weight:750}.draft-message,.practice{display:flex;align-items:center;justify-content:space-between;gap:1rem;padding:1rem;background:#eef1ff;border-left:4px solid #2738d6}.draft-message button,.practice button{padding:.6rem .8rem;border:1px solid #2738d6;background:#fff;font-weight:750}.practice{margin-top:1rem;background:#fffdf8;border:1px solid var(--color-border)}.practice p{margin:.25rem 0;color:var(--color-muted)}.form-card{display:grid;grid-template-columns:3rem 1fr;gap:1.5rem;margin:1.5rem 0;padding:clamp(1.25rem,4vw,2.3rem);border:1px solid var(--color-border);background:#fffdf8;box-shadow:8px 8px 0 #ded8cc}.form-card>b{display:grid;place-items:center;width:2.6rem;height:2.6rem;background:#2738d6;color:#fff}.form-card h2{margin:0;font-family:Georgia,'Times New Roman',serif;font-size:1.8rem;font-weight:500}.form-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:1.15rem;margin-top:1.5rem}.form-grid label{display:grid;gap:.45rem;font-weight:700}.form-grid input,.form-grid select,.form-grid textarea{box-sizing:border-box;width:100%;padding:.8rem;border:1px solid #aaa69e;border-radius:0;background:#fff;font:inherit}.form-grid input:focus,.form-grid select:focus,.form-grid textarea:focus{border-color:#2738d6}.form-grid input[readonly]{background:var(--color-surface-muted)}.form-grid textarea,.no-customers,.wide{grid-column:span 2}.no-customers{padding:1.4rem;color:#fff;background:#17181b}.no-customers p{color:#c5c4bf}.saved-items{display:flex;flex-wrap:wrap;gap:.5rem;margin:1rem 0;padding:.8rem;background:var(--color-surface-muted)}.saved-items strong{flex-basis:100%}.saved-items button{padding:.55rem .7rem;border:1px solid var(--color-border);background:#fff;font:inherit}.review p{font-size:1.05rem;line-height:1.6}.form-actions{display:flex;justify-content:flex-end;align-items:center;gap:1rem;padding-top:1rem}.success{padding:.8rem;background:#e6f7ed;color:var(--color-positive)}@media(max-width:720px){.page-heading{display:block}.draft-badge{display:inline-flex;margin-top:1rem}.practice{align-items:start;flex-direction:column}.form-card{grid-template-columns:1fr;padding:1.25rem;box-shadow:5px 5px 0 #ded8cc}.form-grid{grid-template-columns:1fr}.form-grid textarea,.no-customers,.wide{grid-column:auto}}</style>
